// Layouts that change as the window narrows: what wraps, what fills its row and what stays inside the screen.
const REPOSITORY_ID = uniqueRepositoryId('workbench-responsive');

test.describe.configure({ mode: 'default' });

test.beforeAll(async ({ request }) => {
	await createSeededRepository(request, serverBaseUrl(), REPOSITORY_ID, { graphs: ['bsbm', 'spl'] });
});

test.afterAll(async ({ request }) => {
	await deleteRepository(request, serverBaseUrl(), REPOSITORY_ID);
});

/** The rows a set of boxes form: boxes whose vertical centres lie within 2px share a row. */
function rows(boxes) {
	const result = [];
	for (const box of [...boxes].sort((a, b) => a.top - b.top)) {
		const centre = box.top + box.height / 2;
		const row = result.find(candidate => Math.abs(candidate.centre - centre) <= 2);
		if (row) {
			row.boxes.push(box);
		} else {
			result.push({ centre, boxes: [box] });
		}
	}
	return result.map(row => ({
		left: Math.min(...row.boxes.map(box => box.left)),
		right: Math.max(...row.boxes.map(box => box.right)),
		count: row.boxes.length
	}));
}

/** The list row of a repository in the windowed repository list. */
async function repositoryRow(page, repositoryId) {
	const row = page.locator('#repositories-results tbody tr')
		.filter({ has: page.locator('a.workbench-repository-link', { hasText: new RegExp(`^${repositoryId}$`) }) });
	for (let attempt = 0; attempt < 40 && !(await row.count()); attempt++) {
		await page.mouse.wheel(0, 600);
		await page.waitForTimeout(100);
	}
	await row.scrollIntoViewIfNeeded();
	await page.waitForTimeout(300);
	return row;
}

test('Browse tables fill their card between the phone and desktop layouts', async ({ page }) => {
	for (const width of [900, 768, 640]) {
		await page.setViewportSize({ width, height: 900 });
		await page.goto(repositoryPageUrl(REPOSITORY_ID, 'types'), { waitUntil: 'domcontentloaded' });
		const card = page.locator('#types-results');
		await expect(card.locator('tbody tr').first()).toBeVisible();
		const widths = await card.evaluate(element => ({
			table: element.querySelector('table.data tbody tr').getBoundingClientRect().width,
			header: element.querySelector('.workbench-browse-card__header').getBoundingClientRect().width
		}));
		expect(Math.abs(widths.table - widths.header), `table rows against the card content at ${width}px`).toBeLessThanOrEqual(1);
	}
});

test('An open row menu does not scroll the repository table under its header', async ({ page }) => {
	await page.setViewportSize({ width: 768, height: 900 });
	await page.goto(`${workbenchBaseUrl()}/repositories/NONE/repositories`, { waitUntil: 'domcontentloaded' });
	const row = page.locator('#repositories-results tbody tr').last();
	await expect(row).toBeVisible();
	const header = page.locator('#repositories-results thead th').first();
	const before = await header.boundingBox();
	await row.locator('button[data-workbench-row-menu]').click();
	const remove = row.locator('.workbench-row-menu__panel a', { hasText: 'Delete…' });
	await expect(remove).toBeVisible();
	await remove.scrollIntoViewIfNeeded();
	const after = await header.boundingBox();
	const scrolled = await page.evaluate(() => window.scrollY);
	expect(after.y + scrolled, 'the table header keeps its place in the page').toBeCloseTo(before.y, 0);
	const hit = await remove.evaluate(element => {
		const box = element.getBoundingClientRect();
		return element.contains(document.elementFromPoint(box.left + box.width / 2, box.top + box.height / 2));
	});
	expect(hit, 'Delete… is not clipped by the table').toBe(true);
});

