test('A browse card keeps its filter and action together as the header wraps', async ({ page }) => {
	await page.setViewportSize({ width: 1440, height: 900 });
	await page.goto(repositoryPageUrl(REPOSITORY_ID, 'namespaces'), { waitUntil: 'domcontentloaded' });
	const card = page.locator('#namespaces-results');
	await expect(card.getByRole('button', { name: 'Add namespace' })).toBeVisible();
	for (let width = 1440; width >= 320; width -= 10) {
		await page.setViewportSize({ width, height: 900 });
		const geometry = await card.evaluate(element => {
			const box = (node) => node.getBoundingClientRect().toJSON();
			const input = element.querySelector('.workbench-browse-card__filter input');
			return {
				header: box(element.querySelector('.workbench-browse-card__header')),
				filter: box(element.querySelector('.workbench-browse-card__filter')),
				action: box(element.querySelector('.workbench-browse-card__action')),
				placeholderFits: input.scrollWidth <= input.clientWidth + 1
			};
		});
		const { header, filter, action } = geometry;
		const shared = Math.abs((filter.top + filter.height / 2) - (action.top + action.height / 2)) <= 1;
		expect(Math.abs(action.right - header.right), `the action ends the header at ${width}px`).toBeLessThanOrEqual(1);
		if (width > 600) {
			expect(shared, `filter and action share a row at ${width}px`).toBe(true);
			expect(geometry.placeholderFits, `the filter shows its whole placeholder at ${width}px`).toBe(true);
		} else {
			expect(Math.abs(filter.left - header.left), `the filter starts its row at ${width}px`).toBeLessThanOrEqual(1);
			if (!shared) {
				expect(Math.abs(filter.right - header.right), `the filter fills its row at ${width}px`).toBeLessThanOrEqual(1);
				expect(Math.abs(action.left - header.left), `the action fills its row at ${width}px`).toBeLessThanOrEqual(1);
			}
		}
	}
});

/** The geometry of a phone record: its content box, its fields and its row actions. */
async function recordGeometry(record) {
	return record.evaluate(element => {
		const style = getComputedStyle(element);
		const box = element.getBoundingClientRect();
		const cells = [...element.children].filter(cell => !cell.classList.contains('workbench-row-actions'));
		const first = cells[0].getBoundingClientRect();
		const last = cells[cells.length - 1];
		// A value is the cell's element child, or its text when the cell holds text only.
		const value = (cell) => {
			if (cell.lastElementChild) { return cell.lastElementChild.getBoundingClientRect(); }
			const range = cell.ownerDocument.createRange();
			range.selectNodeContents(cell);
			return range.getBoundingClientRect();
		};
		const actions = [...element.querySelectorAll('.workbench-row-actions :is(button, a)')]
			.filter(action => action.getClientRects().length && !action.closest('[hidden]'))
			.map(action => action.getBoundingClientRect());
		return {
			contentRight: box.right - parseFloat(style.borderRightWidth) - parseFloat(style.paddingRight),
			contentBottom: box.bottom - parseFloat(style.borderBottomWidth) - parseFloat(style.paddingBottom),
			firstTop: first.top, firstBottom: first.bottom,
			firstValueLeft: value(cells[0]).left,
			firstValueRight: value(cells[0]).right,
			secondValueLeft: value(cells[1]).left,
			lastBottom: last.getBoundingClientRect().bottom, lastBorder: parseFloat(getComputedStyle(last).borderBottomWidth),
			actionsBorder: parseFloat(getComputedStyle(element.querySelector('.workbench-row-actions')).borderBottomWidth),
			actionsLeft: Math.min(...actions.map(action => action.left)),
			actionsRight: Math.max(...actions.map(action => action.right)),
			actionsTop: Math.min(...actions.map(action => action.top)),
			actionsBottom: Math.max(...actions.map(action => action.bottom)),
			actionsCentre: actions[0].top + actions[0].height / 2
		};
	});
}

test('A phone record shows its lone row menu beside the first field', async ({ page }) => {
	await page.setViewportSize({ width: 390, height: 900 });
	await page.goto(`${workbenchBaseUrl()}/repositories/NONE/repositories`, { waitUntil: 'domcontentloaded' });
	const record = await repositoryRow(page, REPOSITORY_ID);
	await expect(record).toBeVisible();
	const geometry = await recordGeometry(record);
	expect(geometry.actionsCentre, 'the menu sits on the first field row').toBeGreaterThan(geometry.firstTop);
	expect(geometry.actionsCentre, 'the menu sits on the first field row').toBeLessThan(geometry.firstBottom);
	expect(Math.abs(geometry.actionsRight - geometry.contentRight), 'the menu ends the first field row').toBeLessThanOrEqual(1);
	expect(geometry.firstValueRight, 'the first value stays clear of the menu').toBeLessThanOrEqual(geometry.actionsLeft);
	expect(Math.abs(geometry.firstValueLeft - geometry.secondValueLeft), 'the first value keeps its column').toBeLessThanOrEqual(1);
	expect(Math.abs(geometry.lastBottom - geometry.contentBottom), 'the last field ends the record').toBeLessThanOrEqual(1);
	expect(geometry.lastBorder, 'the last field has no divider below it').toBe(0);
});

test('Phone records end with their row of actions, or their last field when they have none', async ({ page }) => {
	await page.setViewportSize({ width: 390, height: 900 });
	await page.goto(repositoryPageUrl(REPOSITORY_ID, 'namespaces'), { waitUntil: 'domcontentloaded' });
	const record = page.locator('#namespaces-results tbody tr').first();
	await expect(record).toBeVisible();
	const geometry = await recordGeometry(record);
	expect(geometry.actionsTop, 'the actions follow the last field').toBeGreaterThanOrEqual(geometry.lastBottom);
	expect(Math.abs(geometry.actionsRight - geometry.contentRight), 'the actions end their row').toBeLessThanOrEqual(1);
	expect(Math.abs(geometry.actionsBottom - geometry.contentBottom), 'the actions end the record').toBeLessThanOrEqual(1);
	expect(geometry.actionsBorder, 'no divider follows the actions').toBe(0);

	await page.goto(repositoryPageUrl(REPOSITORY_ID, 'contexts'), { waitUntil: 'domcontentloaded' });
	const unnamed = page.locator('#contexts-results tbody tr', { hasText: 'Default graph' });
	await expect(unnamed).toBeVisible();
	const last = await unnamed.evaluate(element => {
		const cells = [...element.children].filter(cell => cell.getClientRects().length);
		const style = getComputedStyle(element);
		return {
			border: parseFloat(getComputedStyle(cells[cells.length - 1]).borderBottomWidth),
			bottom: cells[cells.length - 1].getBoundingClientRect().bottom,
			contentBottom: element.getBoundingClientRect().bottom - parseFloat(style.borderBottomWidth) - parseFloat(style.paddingBottom)
		};
	});
	expect(last.border, 'a record without actions has no divider below its last field').toBe(0);
	expect(Math.abs(last.bottom - last.contentBottom), 'its last field ends the record').toBeLessThanOrEqual(1);
});

/** Asserts that a wrapped toolbar's rows of visible controls each span the toolbar from edge to edge. */
async function expectToolbarRowsFilled(page, selector, width) {
	const geometry = await page.locator(selector).first().evaluate(toolbar => {
		const controls = [...toolbar.querySelectorAll('button, select, input[type="submit"], input[type="button"]')]
			.filter(control => control.getClientRects().length && getComputedStyle(control).visibility !== 'hidden'
				&& !control.closest('[hidden], .workbench-disclosure__panel, [role="dialog"]'))
			.map(control => control.getBoundingClientRect().toJSON());
		const box = toolbar.getBoundingClientRect();
		return { left: box.left, right: box.right, controls };
	});
	const lines = rows(geometry.controls);
	expect(lines.length, `${selector} wraps at ${width}px`).toBeGreaterThan(1);
	for (const line of lines) {
		expect(Math.abs(line.left - geometry.left), `${selector} row starts at the toolbar edge at ${width}px`).toBeLessThanOrEqual(1);
		expect(Math.abs(line.right - geometry.right), `${selector} row ends at the toolbar edge at ${width}px`).toBeLessThanOrEqual(1);
	}
}

test('Query toolbars stay tidy as they wrap on phones', async ({ page }) => {
	for (const width of [390, 320]) {
		await page.setViewportSize({ width, height: 900 });
		await page.goto(repositoryPageUrl(REPOSITORY_ID, 'query'), { waitUntil: 'domcontentloaded' });
		await page.locator('.CodeMirror').first().waitFor();
		await page.evaluate(() => document.querySelector('.CodeMirror').CodeMirror
			.setValue('SELECT ?s ?p ?o WHERE { ?s ?p ?o } LIMIT 5'));
		await expectToolbarRowsFilled(page, '.query-actions-toolbar', width);
		await page.locator('#exec').click();
		await expect(page.locator('.query-result-toolbar').first()).toBeVisible();
		// The result toolbar keeps its controls at their own widths and at its end: Full screen shows its icon only, so
		// the three controls share one row on most phones.
		const results = await page.locator('.query-result-toolbar').first().evaluate(toolbar => {
			const controls = [...toolbar.querySelectorAll('button')]
				.filter(control => control.getClientRects().length && !control.closest('[hidden], .workbench-disclosure__panel'))
				.map(control => control.getBoundingClientRect().toJSON());
			const fullscreen = toolbar.querySelector('.query-results__fullscreen');
			return {
				right: toolbar.getBoundingClientRect().right, controls,
				fullscreenName: fullscreen.getAttribute('aria-label'),
				fullscreen: fullscreen.getBoundingClientRect().toJSON()
			};
		});
		const resultRows = rows(results.controls);
		if (width >= 390) {
			expect(resultRows.length, `the result toolbar fits one row at ${width}px`).toBe(1);
		}
		for (const line of resultRows) {
			expect(Math.abs(line.right - results.right), `result toolbar rows end at its edge at ${width}px`).toBeLessThanOrEqual(1);
		}
		expect(results.fullscreenName).toBe('Full screen');
		expect(Math.abs(results.fullscreen.width - results.fullscreen.height), `Full screen is a square icon at ${width}px`)
			.toBeLessThanOrEqual(1);
		await page.locator('#explain-trigger').click();
		await expect(page.locator('.query-explanation-toolbar').first()).toBeVisible();
		await expectToolbarRowsFilled(page, '.query-explanation-toolbar', width);
	}
});

test('A scrolled result toolbar never hides its controls under the context bar', async ({ page }) => {
	for (const width of [1440, 390]) {
		await page.setViewportSize({ width, height: 700 });
		await page.goto(repositoryPageUrl(REPOSITORY_ID, 'query'), { waitUntil: 'domcontentloaded' });
		await page.locator('.CodeMirror').first().waitFor();
		await page.evaluate(() => document.querySelector('.CodeMirror').CodeMirror
			.setValue('SELECT ?s ?p ?o WHERE { ?s ?p ?o } LIMIT 60'));
		await page.locator('#exec').click();
		const toolbar = page.locator('#query-results .query-result-toolbar');
		await expect(toolbar).toBeVisible();
		await expect(page.locator('#query-results [aria-busy="false"], #query-results[aria-busy="false"]').first()).toBeAttached();
		await page.waitForTimeout(800);
		await page.evaluate(() => scrollTo(0, document.querySelector('#query-results .query-result-toolbar')
			.getBoundingClientRect().top + scrollY + 400));
		await page.waitForTimeout(300);
		const covered = await toolbar.evaluate(element => [...element.querySelectorAll('button')]
			.filter(button => button.getClientRects().length && !button.closest('[hidden]'))
			.filter(button => {
				const box = button.getBoundingClientRect();
				const y = box.top + box.height / 2;
				if (y < 0 || y > innerHeight) { return false; }
				return !button.contains(document.elementFromPoint(box.left + box.width / 2, y));
			})
			.map(button => button.getAttribute('aria-label') || button.textContent.trim()));
		expect(covered, `result toolbar controls covered after scrolling at ${width}px`).toEqual([]);
	}
});

