test('Warnings never end on a lone word', async ({ page, browserName }) => {
	test.skip(browserName !== 'chromium', 'Balanced last lines rely on text-wrap: pretty, which only Chromium implements.');
	await page.setViewportSize({ width: 1440, height: 900 });
	await page.goto(repositoryPageUrl(REPOSITORY_ID, 'clear'), { waitUntil: 'domcontentloaded' });
	const warning = page.locator('#clear-warning');
	await expect(warning).toBeVisible();
	for (let width = 1440; width >= 320; width -= 10) {
		await page.setViewportSize({ width, height: 900 });
		const lastLineWords = await warning.evaluate(element => {
			const words = [];
			const walker = element.ownerDocument.createTreeWalker(element, NodeFilter.SHOW_TEXT);
			for (let node = walker.nextNode(); node; node = walker.nextNode()) {
				for (const match of node.textContent.matchAll(/\S+/g)) {
					const range = element.ownerDocument.createRange();
					range.setStart(node, match.index);
					range.setEnd(node, match.index + match[0].length);
					const rect = range.getClientRects()[0];
					if (rect) { words.push(rect.top); }
				}
			}
			const last = Math.max(...words);
			return words.filter(top => Math.abs(top - last) < 2).length;
		});
		expect(lastLineWords, `words on the last line of the warning at ${width}px`).toBeGreaterThan(1);
	}
});

test('Phone namespace records break IRIs only after their separators', async ({ page }) => {
	await page.setViewportSize({ width: 390, height: 900 });
	await page.goto(repositoryPageUrl(REPOSITORY_ID, 'namespaces'), { waitUntil: 'domcontentloaded' });
	await expect(page.locator('#namespaces-results tbody tr').first()).toBeVisible();
	const breaks = await page.locator('#namespaces-results td[data-label="Namespace"] code').evaluateAll(codes => codes.flatMap(code => {
		const characters = [];
		const walker = code.ownerDocument.createTreeWalker(code, NodeFilter.SHOW_TEXT);
		for (let node = walker.nextNode(); node; node = walker.nextNode()) {
			for (let index = 0; index < node.textContent.length; index++) {
				const range = code.ownerDocument.createRange();
				range.setStart(node, index);
				range.setEnd(node, index + 1);
				const rect = range.getClientRects()[0];
				if (rect) { characters.push({ character: node.textContent.charAt(index), top: rect.top }); }
			}
		}
		const result = [];
		for (let index = 1; index < characters.length; index++) {
			if (characters[index].top > characters[index - 1].top + 2) {
				result.push(code.textContent.slice(0, index) + ' | ' + code.textContent.slice(index));
			}
		}
		return result;
	}));
	expect(breaks.length, 'some namespaces wrap at this width').toBeGreaterThan(0);
	for (const line of breaks) {
		expect(line, 'a namespace line ends with / # : or -').toMatch(/[/#:-] \| /);
	}
});
